import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';
import { lineTotal, lineDiscount, lineVAT, invoiceTotals } from './totals.js';

// Re-export for backwards compatibility
export { lineTotal, lineDiscount, lineVAT, invoiceTotals };

/**
 * Calculate due date based on payment terms.
 * @param {string} issueDate - Date in YYYY-MM-DD format
 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
 * @returns {string} - Due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    // Last day of the month
    const [year, month] = issueDate.split('-').map(Number);
    const nextMonth = new Date(Date.UTC(year, month, 1)); // 1st of next month
    nextMonth.setUTCDate(0); // Go back to last day of current month
    const lastDay = String(nextMonth.getUTCDate()).padStart(2, '0');
    return `${year}-${String(month).padStart(2, '0')}-${lastDay}`;
  }
  return null;
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize and validate customer
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate issueDate
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate and calculate due date
  if (!['NET14', 'NET30', 'EOM'].includes(terms)) {
    return fail('TERMS_INVALID');
  }
  const dueDate = calculateDueDate(issueDate, terms);

  // Validate lines
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and build invoice lines
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Determine discountPercent: explicit value wins, otherwise use tier discount
    let discountPercent;
    if (line.discountPercent !== undefined) {
      discountPercent = line.discountPercent;
    } else {
      discountPercent = TIER_DISCOUNTS[customer.tier];
    }

    // Validate discountPercent
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }

    // Get product info
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
    terms,
    dueDate,
  });
}


/**
 * Add a line to a draft invoice, or increase qty if the SKU already exists.
 * @param {{ status: string, customerId: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discountPercent if provided
  if (discountPercent !== undefined && (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100)) {
    return fail('DISCOUNT_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  // Get customer to determine tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const product = productResult.value;
  const customer = customerResult.value;

  // Determine discountPercent: explicit value wins, otherwise use tier discount
  let newDiscountPercent;
  if (discountPercent !== undefined) {
    newDiscountPercent = discountPercent;
  } else {
    newDiscountPercent = TIER_DISCOUNTS[customer.tier];
  }

  const existingLine = invoice.lines.find((line) => line.sku === sku);
  const newLines = invoice.lines.map((line) =>
    line.sku === sku ? { ...line, qty: line.qty + qty, discountPercent: newDiscountPercent } : line
  );

  if (!existingLine) {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: newDiscountPercent,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers
 * @returns {{ ok: true, value: { status: string, number: string } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: object }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Validate invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate no voucher already exists
  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  // Validate amount
  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

