  const result = invoiceTotals(invoice);
  // Line 1: subtotal 95000, line discount 9500, bulk discount 2138, VAT on 83362 = 17506
  // Line 2: subtotal 10000, discount 500, no bulk, VAT on 9500 = 855
  // Total: 105000 - 12138 + 18361 = 111223
  assert.equal(result.subtotal, 105000);
  assert.equal(result.discount, 12138);
  assert.equal(result.vat, 18361);
  assert.equal(result.total, 111223);
});

test('invoiceTotals total is clamped to 0', () => {
