test('bulkDiscount returns 0 for less than 10 units', () => {
  assert.equal(bulkDiscount({ qty: 1, unitPrice: 9500, discountPercent: 0 }), 0);
  assert.equal(bulkDiscount({ qty: 5, unitPrice: 9500, discountPercent: 0 }), 0);
  assert.equal(bulkDiscount({ qty: 9, unitPrice: 9500, discountPercent: 0 }), 0);
