test('bulkDiscount returns 2.5% of amount after first discount for 10+ units', () => {
  // qty: 10, unitPrice: 10000, total: 100000
  // No line discount, so amount after = 100000
  // Bulk discount = 100000 * 0.025 = 2500
  assert.equal(bulkDiscount({ qty: 10, unitPrice: 10000, discountPercent: 0 }), 2500);
});

test('bulkDiscount applied to amount after line discount', () => {
  // qty: 10, unitPrice: 10000, total: 100000
  // Line discount: 10% = 10000, amount after: 90000
  // Bulk discount: 90000 * 0.025 = 2250
  assert.equal(bulkDiscount({ qty: 10, unitPrice: 10000, discountPercent: 10 }), 2250);
});

test('bulkDiscount with higher line discount', () => {
  // qty: 10, unitPrice: 10000, total: 100000
  // Line discount: 20% = 20000, amount after: 80000
  // Bulk discount: 80000 * 0.025 = 2000
  assert.equal(bulkDiscount({ qty: 10, unitPrice: 10000, discountPercent: 20 }), 2000);
});

test('bulkDiscount with large quantity', () => {
  // qty: 100, unitPrice: 1000, total: 100000
  // No line discount, amount after: 100000
  // Bulk discount: 100000 * 0.025 = 2500
  assert.equal(bulkDiscount({ qty: 100, unitPrice: 1000, discountPercent: 0 }), 2500);
});

test('lineVAT with bulk discount', () => {
  // qty: 10, unitPrice: 10000, total: 100000
  // Line discount: 0, bulk discount: 2500
  // Amount for VAT: 100000 - 0 - 2500 = 97500
  // VAT at 21%: 97500 * 0.21 = 20475
  assert.equal(lineVAT({ qty: 10, unitPrice: 10000, discountPercent: 0, vatRate: 21 }), 20475);
});

test('lineVAT with both discounts', () => {
  // qty: 10, unitPrice: 10000, total: 100000
  // Line discount: 10% = 10000, bulk discount: 2250
  // Amount for VAT: 100000 - 10000 - 2250 = 87750
  // VAT at 21%: 87750 * 0.21 = 18427.5 → 18428
  assert.equal(lineVAT({ qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 }), 18428);
});

test('invoiceTotals with bulk discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 10000, discountPercent: 0, vatRate: 21 }],
  };

  const result = invoiceTotals(invoice);
  // subtotal: 100000
  // discount: 0 (line) + 2500 (bulk) = 2500
  // vat: 97500 * 0.21 = 20475
  // total: 100000 - 2500 + 20475 = 117975
  assert.equal(result.subtotal, 100000);
  assert.equal(result.discount, 2500);
  assert.equal(result.vat, 20475);
  assert.equal(result.total, 117975);
});

test('invoiceTotals with line discount and bulk discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 }],
  };

  const result = invoiceTotals(invoice);
  // subtotal: 100000
  // line discount: 10000, bulk discount: 2250, total discount: 12250
  // vat: 87750 * 0.21 = 18427.5 → 18428
  // total: 100000 - 12250 + 18428 = 106178
  assert.equal(result.subtotal, 100000);
  assert.equal(result.discount, 12250);
  assert.equal(result.vat, 18428);
  assert.equal(result.total, 106178);
});

test('invoiceTotals with mixed quantities', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 10000, discountPercent: 0, vatRate: 21 }, // no bulk discount
      { qty: 10, unitPrice: 10000, discountPercent: 0, vatRate: 21 }, // bulk discount
    ],
  };

  const result = invoiceTotals(invoice);
  // Line 1: subtotal 50000, no discount, vat 10500, total 60500
  // Line 2: subtotal 100000, bulk discount 2500, vat 20475, total 117975
  // Combined: subtotal 150000, discount 2500, vat 30975, total 178475
  assert.equal(result.subtotal, 150000);
  assert.equal(result.discount, 2500);
  assert.equal(result.vat, 30975);
  assert.equal(result.total, 178475);
});

test('invoiceTotals with 9 units no bulk, 10 units with bulk', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };

  const result = invoiceTotals(invoice);
  // Line 1: subtotal 9000, discount 0, vat 0
  // Line 2: subtotal 10000, bulk discount 250, vat 0
  // Total: subtotal 19000, discount 250, vat 0, total 18750
  assert.equal(result.subtotal, 19000);
  assert.equal(result.discount, 250);
  assert.equal(result.vat, 0);
  assert.equal(result.total, 18750);
});

test('invoiceTotals bulk discount at threshold', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1, discountPercent: 0, vatRate: 0 }],
  };

  const result = invoiceTotals(invoice);
  // qty 10 gets bulk discount
